-- ============================================================================
-- B5 FOLLOW-ON W1 (grade integrity): mbal.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 4 and
-- the annotations in docs/graded-field-audit/annot/mbal.json. Owner
-- approved D1 to D7 as recommended, 2026-09-21.
--
-- BEGINNER
--   r_squared graded exactly 1 (a synthetic tank on a perfect line), so typing 1
--   passed with no work. Replaced by the oil expansion Eo at the last survey,
--   read from the Eo column of the Tank explorer survey table (7 dp) and
--   hand-checkable as Bo less 1.2 or Et less Efw.
--   RE-KEY r_squared (expected 1, tol 0.001)
--       -> eo_last_rb_stb 'Oil expansion Eo at the last survey' rb/stb, expected 0.01589748101759514, tol 5e-05
--   PROMPT was: the depletion drive index, and the quality of the straight line
--   itself.
--   PROMPT now: the depletion drive index, and the oil expansion Eo at the last
--   survey.
--
-- INTERMEDIATE
--   TIGHTEN pot_r2 (expected 0.999485673716372) tol 0.002 -> 0.0001:
--       a blind 1 or 0.999 passed at 0.002; the tile prints 12 significant figures
--
-- ADVANCED
--   a111_index_sum graded the sum of the four Ahmed 11-1 drive indices under the
--   net convention, which is 1 by identity, so 1 passed with no work. Replaced
--   by the depletion drive index under the same net convention, N Eo / A, which
--   still separates the conventions (gross gives 0.42609, 0.0125 away).
--   RE-KEY a111_index_sum (expected 1, tol 0.002)
--       -> a111_ddi 'Ahmed 11-1 depletion drive index, net convention' -, expected 0.43854519939188374, tol 0.002
--   PROMPT was: the water influx, the water drive index, and the sum of the four
--   indices under the convention that actually closes.
--   PROMPT now: the water influx, the water drive index, and the depletion drive
--   index, each under the convention that actually closes.
--
-- WHAT DOES NOT MOVE. Every other field (key, label, unit, expected, tol and
-- position), the title, dataset, status and the row itself.
--
-- ATTEMPTS. Tiers whose graded key or tolerance moves: mbal/beginner,
-- mbal/intermediate, mbal/advanced. Before it writes, the file counts
-- academy_capstone_attempts on each and REFUSES if any exist, unless D5
-- allowlists that tier with the exact attempt ids (allowlist: empty). Stored
-- scores are never touched.
--
-- GUARDS. Each row must hold EITHER its published prompt (by md5) and fields
-- (exact jsonb) as the post-20261023 scratch replay has them (it is
-- rewritten), OR its W1 form (left alone). Anything else raises and the whole
-- file rolls back. A file that will write first checks the round-off
-- post-state (20261023*) and refuses without it. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- mbal / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'mbal' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 mbal refused: mbal/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '9e82ce39d21555693f2c4b487fc80d50' and fields = '[{"key": "f_last_rb", "tol": 50, "unit": "rb", "label": "Underground withdrawal F at the last survey", "expected": 317926.842484584}, {"key": "et_last_rb", "tol": 0.00005, "unit": "rb/stb", "label": "Total expansion Et at the last survey", "expected": 0.0261900809071921}, {"key": "ooip_stb", "tol": 20000, "unit": "stb", "label": "OOIP from the Havlena-Odeh slope", "expected": 12139208.1074968}, {"key": "efw_share_pct", "tol": 0.2, "unit": "%", "label": "Efw share of Et at the last survey", "expected": 39.2996108949418}, {"key": "ddi_final", "tol": 0.005, "unit": "-", "label": "Depletion drive index at the last survey", "expected": 0.607003891050583}, {"key": "r_squared", "tol": 0.001, "unit": "-", "label": "R-squared of the straight line", "expected": 1}]'::jsonb then 'old'
              when md5(prompt) = 'd97798a4c92de4bab4c50aab77bf8def' and fields = '[{"key": "f_last_rb", "tol": 50, "unit": "rb", "label": "Underground withdrawal F at the last survey", "expected": 317926.842484584}, {"key": "et_last_rb", "tol": 0.00005, "unit": "rb/stb", "label": "Total expansion Et at the last survey", "expected": 0.0261900809071921}, {"key": "ooip_stb", "tol": 20000, "unit": "stb", "label": "OOIP from the Havlena-Odeh slope", "expected": 12139208.1074968}, {"key": "efw_share_pct", "tol": 0.2, "unit": "%", "label": "Efw share of Et at the last survey", "expected": 39.2996108949418}, {"key": "ddi_final", "tol": 0.005, "unit": "-", "label": "Depletion drive index at the last survey", "expected": 0.607003891050583}, {"key": "eo_last_rb_stb", "tol": 5e-05, "unit": "rb/stb", "label": "Oil expansion Eo at the last survey", "expected": 0.01589748101759514}]'::jsonb then 'new'
              when md5(prompt) = 'a2b66f64989dd5f799aea0c2173f067c' and fields = '[{"key": "f_last_rb", "tol": 50, "unit": "rb", "label": "Underground withdrawal F at the last survey", "expected": 317926.842484584}, {"key": "et_last_rb", "tol": 0.00005, "unit": "rb/stb", "label": "Total expansion Et at the last survey", "expected": 0.0261900809071921}, {"key": "ooip_stb", "tol": 20000, "unit": "stb", "label": "OOIP from the Havlena-Odeh slope", "expected": 12139208.1074968}, {"key": "efw_share_pct", "tol": 0.2, "unit": "%", "label": "Efw share of Et at the last survey", "expected": 39.2996108949418}, {"key": "ddi_final", "tol": 0.005, "unit": "-", "label": "Depletion drive index at the last survey", "expected": 0.607003891050583}, {"key": "eo_last_rb_stb", "tol": 5e-05, "unit": "rb/stb", "label": "Oil expansion Eo at the last survey", "expected": 0.01589748101759514}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'mbal' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 mbal refused: mbal/beginner matches neither its published form (prompt md5 9e82ce39d21555693f2c4b487fc80d50) nor its W1 form (prompt md5 d97798a4c92de4bab4c50aab77bf8def), with the fields this file was generated against';
  end if;

  -- mbal / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'mbal' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 mbal refused: mbal/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '17afd148a2efd39c8e142884e008a340' and fields = '[{"key": "wei_bbl", "tol": 500000, "unit": "bbl", "label": "Fetkovich Wei for Ahmed 10-10", "expected": 211934253.721285}, {"key": "j_bbl_d_psi", "tol": 0.5, "unit": "bbl/d/psi", "label": "Aquifer productivity index J", "expected": 116.496154838747}, {"key": "decay_365", "tol": 0.002, "unit": "-", "label": "Decay term over one 365 day step", "expected": 0.422897624804177}, {"key": "we_final_mmbbl", "tol": 0.4, "unit": "MMbbl", "label": "Cumulative We after four steps", "expected": 37.9731544101719}, {"key": "pot_ooip_stb", "tol": 20000, "unit": "stb", "label": "OOIP when a pot aquifer is forced on Ekene", "expected": -516449.043355256}, {"key": "pot_r2", "tol": 0.002, "unit": "-", "label": "R-squared of that wrong-model fit", "expected": 0.999485673716372}]'::jsonb then 'old'
              when md5(prompt) = '17afd148a2efd39c8e142884e008a340' and fields = '[{"key": "wei_bbl", "tol": 500000, "unit": "bbl", "label": "Fetkovich Wei for Ahmed 10-10", "expected": 211934253.721285}, {"key": "j_bbl_d_psi", "tol": 0.5, "unit": "bbl/d/psi", "label": "Aquifer productivity index J", "expected": 116.496154838747}, {"key": "decay_365", "tol": 0.002, "unit": "-", "label": "Decay term over one 365 day step", "expected": 0.422897624804177}, {"key": "we_final_mmbbl", "tol": 0.4, "unit": "MMbbl", "label": "Cumulative We after four steps", "expected": 37.9731544101719}, {"key": "pot_ooip_stb", "tol": 20000, "unit": "stb", "label": "OOIP when a pot aquifer is forced on Ekene", "expected": -516449.043355256}, {"key": "pot_r2", "tol": 0.0001, "unit": "-", "label": "R-squared of that wrong-model fit", "expected": 0.999485673716372}]'::jsonb then 'new'
              when md5(prompt) = '18a6332ea1f24ba62671247be2020252' and fields = '[{"key": "wei_bbl", "tol": 500000, "unit": "bbl", "label": "Fetkovich Wei for Ahmed 10-10", "expected": 211934253.721285}, {"key": "j_bbl_d_psi", "tol": 0.5, "unit": "bbl/d/psi", "label": "Aquifer productivity index J", "expected": 116.496154838747}, {"key": "decay_365", "tol": 0.002, "unit": "-", "label": "Decay term over one 365 day step", "expected": 0.422897624804177}, {"key": "we_final_mmbbl", "tol": 0.4, "unit": "MMbbl", "label": "Cumulative We after four steps", "expected": 37.9731544101719}, {"key": "pot_ooip_stb", "tol": 20000, "unit": "stb", "label": "OOIP when a pot aquifer is forced on Ekene", "expected": -516449.043355256}, {"key": "pot_r2", "tol": 0.0001, "unit": "-", "label": "R-squared of that wrong-model fit", "expected": 0.999485673716372}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'mbal' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 mbal refused: mbal/intermediate matches neither its published form (prompt md5 17afd148a2efd39c8e142884e008a340) nor its W1 form (prompt md5 17afd148a2efd39c8e142884e008a340), with the fields this file was generated against';
  end if;

  -- mbal / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'mbal' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 mbal refused: mbal/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'fbc71171d5c125ce53bb016dbbaf73d6' and fields = '[{"key": "dake_ooip_mmstb", "tol": 3, "unit": "MMSTB", "label": "Dake 9.2 OOIP from Carter-Tracy", "expected": 307.221409553720}, {"key": "dake_we_mmrb", "tol": 1, "unit": "MMrb", "label": "Dake 9.2 cumulative water influx", "expected": 88.0645883139400}, {"key": "pd_finite_100", "tol": 0.05, "unit": "-", "label": "Bounded-circle pD at reD 5, tD 100", "expected": 9.30886079703705}, {"key": "a111_we_bbl", "tol": 500, "unit": "bbl", "label": "Ahmed 11-1 water influx We", "expected": 411281.250000001}, {"key": "a111_wdi", "tol": 0.002, "unit": "-", "label": "Ahmed 11-1 water drive index", "expected": 0.211250877090399}, {"key": "a111_index_sum", "tol": 0.002, "unit": "-", "label": "Ahmed 11-1 drive indices summed", "expected": 1}]'::jsonb then 'old'
              when md5(prompt) = '4a6a40d31bb365b41a1667497b8a0a8e' and fields = '[{"key": "dake_ooip_mmstb", "tol": 3, "unit": "MMSTB", "label": "Dake 9.2 OOIP from Carter-Tracy", "expected": 307.221409553720}, {"key": "dake_we_mmrb", "tol": 1, "unit": "MMrb", "label": "Dake 9.2 cumulative water influx", "expected": 88.0645883139400}, {"key": "pd_finite_100", "tol": 0.05, "unit": "-", "label": "Bounded-circle pD at reD 5, tD 100", "expected": 9.30886079703705}, {"key": "a111_we_bbl", "tol": 500, "unit": "bbl", "label": "Ahmed 11-1 water influx We", "expected": 411281.250000001}, {"key": "a111_wdi", "tol": 0.002, "unit": "-", "label": "Ahmed 11-1 water drive index", "expected": 0.211250877090399}, {"key": "a111_ddi", "tol": 0.002, "unit": "-", "label": "Ahmed 11-1 depletion drive index, net convention", "expected": 0.43854519939188374}]'::jsonb then 'new'
              when md5(prompt) = 'fd372e1e2039a84d12c0de1b730f149f' and fields = '[{"key": "dake_ooip_mmstb", "tol": 3, "unit": "MMSTB", "label": "Dake 9.2 OOIP from Carter-Tracy", "expected": 307.221409553720}, {"key": "dake_we_mmrb", "tol": 1, "unit": "MMrb", "label": "Dake 9.2 cumulative water influx", "expected": 88.0645883139400}, {"key": "pd_finite_100", "tol": 0.05, "unit": "-", "label": "Bounded-circle pD at reD 5, tD 100", "expected": 9.30886079703705}, {"key": "a111_we_bbl", "tol": 500, "unit": "bbl", "label": "Ahmed 11-1 water influx We", "expected": 411281.250000001}, {"key": "a111_wdi", "tol": 0.002, "unit": "-", "label": "Ahmed 11-1 water drive index", "expected": 0.211250877090399}, {"key": "a111_ddi", "tol": 0.002, "unit": "-", "label": "Ahmed 11-1 depletion drive index, net convention", "expected": 0.43854519939188374}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'mbal' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w1 mbal refused: mbal/advanced matches neither its published form (prompt md5 fbc71171d5c125ce53bb016dbbaf73d6) nor its W1 form (prompt md5 4a6a40d31bb365b41a1667497b8a0a8e), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w1 mbal: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 mbal refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  -- ATTEMPTS. A tier whose graded key or tolerance this file moves must hold no
  -- capstone attempt (a stored score is never re-scored, but a learner could be
  -- graded differently on a retry of the same brief), unless D5 allowlists it
  -- with the exact attempt ids signed off. Any other attempt refuses.
  if v_s0 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'mbal' and a.tier = 'beginner';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'mbal/beginner' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'mbal/beginner') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_extra) x;
          raise exception 'w1 mbal refused: mbal/beginner holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_idtxt;
        end if;
        raise notice 'w1 mbal: mbal/beginner holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_ids) x;
        raise exception 'w1 mbal refused: mbal/beginner holds % capstone attempt(s) (%) and this file moves its graded key or tolerance; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_idtxt;
      end if;
    end if;
  end if;
  if v_s1 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'mbal' and a.tier = 'intermediate';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'mbal/intermediate' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'mbal/intermediate') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_extra) x;
          raise exception 'w1 mbal refused: mbal/intermediate holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_idtxt;
        end if;
        raise notice 'w1 mbal: mbal/intermediate holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_ids) x;
        raise exception 'w1 mbal refused: mbal/intermediate holds % capstone attempt(s) (%) and this file moves its graded key or tolerance; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_idtxt;
      end if;
    end if;
  end if;
  if v_s2 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'mbal' and a.tier = 'advanced';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'mbal/advanced' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'mbal/advanced') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_extra) x;
          raise exception 'w1 mbal refused: mbal/advanced holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_idtxt;
        end if;
        raise notice 'w1 mbal: mbal/advanced holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_ids) x;
        raise exception 'w1 mbal refused: mbal/advanced holds % capstone attempt(s) (%) and this file moves its graded key or tolerance; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_idtxt;
      end if;
    end if;
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Run material balance on the Ekene survey history and read the tank: the underground withdrawal and the total expansion at the last survey, the oil in place the Havlena-Odeh straight line gives, the share of that expansion carried by rock and connate water, the depletion drive index, and the oil expansion Eo at the last survey.',
           fields = '[{"key": "f_last_rb", "tol": 50, "unit": "rb", "label": "Underground withdrawal F at the last survey", "expected": 317926.842484584}, {"key": "et_last_rb", "tol": 0.00005, "unit": "rb/stb", "label": "Total expansion Et at the last survey", "expected": 0.0261900809071921}, {"key": "ooip_stb", "tol": 20000, "unit": "stb", "label": "OOIP from the Havlena-Odeh slope", "expected": 12139208.1074968}, {"key": "efw_share_pct", "tol": 0.2, "unit": "%", "label": "Efw share of Et at the last survey", "expected": 39.2996108949418}, {"key": "ddi_final", "tol": 0.005, "unit": "-", "label": "Depletion drive index at the last survey", "expected": 0.607003891050583}, {"key": "eo_last_rb_stb", "tol": 5e-05, "unit": "rb/stb", "label": "Oil expansion Eo at the last survey", "expected": 0.01589748101759514}]'::jsonb
     where app_slug = 'mbal' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 mbal refused: mbal/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'd97798a4c92de4bab4c50aab77bf8def' and fields = '[{"key": "f_last_rb", "tol": 50, "unit": "rb", "label": "Underground withdrawal F at the last survey", "expected": 317926.842484584}, {"key": "et_last_rb", "tol": 0.00005, "unit": "rb/stb", "label": "Total expansion Et at the last survey", "expected": 0.0261900809071921}, {"key": "ooip_stb", "tol": 20000, "unit": "stb", "label": "OOIP from the Havlena-Odeh slope", "expected": 12139208.1074968}, {"key": "efw_share_pct", "tol": 0.2, "unit": "%", "label": "Efw share of Et at the last survey", "expected": 39.2996108949418}, {"key": "ddi_final", "tol": 0.005, "unit": "-", "label": "Depletion drive index at the last survey", "expected": 0.607003891050583}, {"key": "eo_last_rb_stb", "tol": 5e-05, "unit": "rb/stb", "label": "Oil expansion Eo at the last survey", "expected": 0.01589748101759514}]'::jsonb)
        or (md5(prompt) = 'a2b66f64989dd5f799aea0c2173f067c' and fields = '[{"key": "f_last_rb", "tol": 50, "unit": "rb", "label": "Underground withdrawal F at the last survey", "expected": 317926.842484584}, {"key": "et_last_rb", "tol": 0.00005, "unit": "rb/stb", "label": "Total expansion Et at the last survey", "expected": 0.0261900809071921}, {"key": "ooip_stb", "tol": 20000, "unit": "stb", "label": "OOIP from the Havlena-Odeh slope", "expected": 12139208.1074968}, {"key": "efw_share_pct", "tol": 0.2, "unit": "%", "label": "Efw share of Et at the last survey", "expected": 39.2996108949418}, {"key": "ddi_final", "tol": 0.005, "unit": "-", "label": "Depletion drive index at the last survey", "expected": 0.607003891050583}, {"key": "eo_last_rb_stb", "tol": 5e-05, "unit": "rb/stb", "label": "Oil expansion Eo at the last survey", "expected": 0.01589748101759514}]'::jsonb) from public.academy_capstones where app_slug = 'mbal' and tier = 'beginner' and active) is not true then
    raise exception 'w1 mbal refused: mbal/beginner does not read back as its W1 form';
  end if;

